window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-19591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θόρυβος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra θ · nº geral 19591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rumor; burburinho 2 clamor (de aprovação); aplauso 3 murmúrio; clamor hostil (de de­saprovação); vaia 4 barulho; tumulto.</p></section></article>\n<article id=\"entry-dgp-19592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θορυβώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra θ · nº geral 19592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barulhento; tumultuoso 2 perturbador; assustador. 〈θόρυβος〉</p></section></article>\n<article id=\"entry-dgp-19593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θορυβωδῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra θ · nº geral 19593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. tumultuosamente.</p></section></article>\n<article id=\"entry-dgp-19594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θορών</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra θ · nº geral 19594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de θρῴσκω.</p></section></article>\n<article id=\"entry-dgp-19595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra θ · nº geral 19595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor.2 méd. de τίθημι.</p></section></article>\n<article id=\"entry-dgp-19596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θουκυδίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra θ · nº geral 19596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tucídides, historiador. 〈θεός, κῦδος〉</p></section></article>\n<article id=\"entry-dgp-19597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θουρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra θ · nº geral 19597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Túria, cidade da Messênia.</p></section></article>\n<article id=\"entry-dgp-19598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θουριάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 551 na letra θ · nº geral 19598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Túrio. 〈Θούριον〉</p></section></article>\n<article id=\"entry-dgp-19599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θουριάτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 552 na letra θ · nº geral 19599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de Túria, cidade da Messênia ♦ οἱ Θουριᾶται 2 habitante de Túria.</p></section></article>\n<article id=\"entry-dgp-19600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θούριοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 553 na letra θ · nº geral 19600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Túrios ou Túrio, cidade da Lucânia e colônia de Atenas.</p></section></article>\n<article id=\"entry-dgp-19601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θούριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 554 na letra θ · nº geral 19601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Θούριοι.</p></section></article>\n<article id=\"entry-dgp-19602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θούριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 555 na letra θ · nº geral 19602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Túrio ♦ ἡ Θουρία [χώρα] 2 território de Túrio.</p></section></article>\n<article id=\"entry-dgp-19603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θούριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 556 na letra θ · nº geral 19603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θοῦρος.</p></section></article>\n<article id=\"entry-dgp-19604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θοῦρις, ιδος,</h1><div class=\"entry-meta\"><span>DGP · ordem 557 na letra θ · nº geral 19604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. -ιν (fem.) 1 impetuoso 2 terrível; ousado.</p></section></article>\n<article id=\"entry-dgp-19605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θοὔρμαιον</h1><div class=\"entry-meta\"><span>DGP · ordem 558 na letra θ · nº geral 19605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de τὸ ἕρμαιον.</p></section></article>\n<article id=\"entry-dgp-19606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θοῦρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 559 na letra θ · nº geral 19606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 impetuoso; fogoso; ousado, epít. de Ares, de Tífon 2 veemente.</p></section></article>\n<article id=\"entry-dgp-19607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θόωκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 560 na letra θ · nº geral 19607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. 1 assento 2 sessão de uma assembléia.</p></section></article>\n<article id=\"entry-dgp-19608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θοῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 561 na letra θ · nº geral 19608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 rapidamente; prontamente 2 logo.</p></section></article>\n<article id=\"entry-dgp-19609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 562 na letra θ · nº geral 19609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estalo; crepitação. 〈θράσσω〉</p></section></article>\n<article id=\"entry-dgp-19610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾷκες</h1><div class=\"entry-meta\"><span>DGP · ordem 563 na letra θ · nº geral 19610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Θρᾴξ.</p></section></article>\n<article id=\"entry-dgp-19611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾷκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 564 na letra θ · nº geral 19611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Trácia, região da Europa e da Ásia, entre a Propôntida e o mar Egeu. 〈Θρᾷξ〉</p></section></article>\n<article id=\"entry-dgp-19612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρακικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 565 na letra θ · nº geral 19612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Trácia. 〈Θρᾴξ〉</p></section></article>\n<article id=\"entry-dgp-19613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾴκιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 566 na letra θ · nº geral 19613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Trácia. 〈Θρᾷξ〉</p></section></article>\n<article id=\"entry-dgp-19614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρανίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 567 na letra θ · nº geral 19614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">banco; escabelo. 〈θρᾶνος〉</p></section></article>\n<article id=\"entry-dgp-19615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρανίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 568 na letra θ · nº geral 19615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 remador do banco superior ♦ adj. 2 do banco superior. 〈θρᾶνος〉</p></section></article>\n<article id=\"entry-dgp-19616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾶνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 569 na letra θ · nº geral 19616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">assento; banco; escabelo.</p></section></article>\n<article id=\"entry-dgp-19617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾷξ, Θρᾳκός</h1><div class=\"entry-meta\"><span>DGP · ordem 570 na letra θ · nº geral 19617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) da Trácia, trácio.</p></section></article>\n<article id=\"entry-dgp-19618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασέως</h1><div class=\"entry-meta\"><span>DGP · ordem 571 na letra θ · nº geral 19618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. (comp. θρασύτερον, superl. θρασύτατα) ousadamente; audaciosamente. 〈θρασύς〉</p></section></article>\n<article id=\"entry-dgp-19619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θράσος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 572 na letra θ · nº geral 19619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 resolução; ousadia; coragem 2 confiança em, gen. 3 audácia; temeridade: εἰς τοῦτο θράσους ἀνήκει her. ele chegou a esse grau de audácia, προβᾶσ᾽ ἐπ᾽ ἔσχατον θράσους sóf. tendo chegado ao último grau de audácia 4 impudência.</p></section></article>\n<article id=\"entry-dgp-19620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾷσσα,</h1><div class=\"entry-meta\"><span>DGP · ordem 573 na letra θ · nº geral 19620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Θρᾷττα, ης (fem.) 1 da Trácia; trácia ♦ ἡ Θρᾷσσα 2 mulher trácia. 〈Θρᾷξ〉</p></section></article>\n<article id=\"entry-dgp-19621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 574 na letra θ · nº geral 19621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. θράττω (fut. desus., aor. ἔθραξα, perf. jôn. intr. τέτρηχα, aor. pas. ἐθράχθην) perturbar; agitar; transtornar.</p></section></article>\n<article id=\"entry-dgp-19622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασυκάρδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 575 na letra θ · nº geral 19622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de coração ousado. 〈θρασύς, καρδία〉</p></section></article>\n<article id=\"entry-dgp-19623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύμαχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 576 na letra θ · nº geral 19623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ousado em combate. 〈θρασύς, μάχη〉</p></section></article>\n<article id=\"entry-dgp-19624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασυμέμνων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 577 na letra θ · nº geral 19624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος resoluto; ousado; intrépido. 〈θρασύς, μέμνων〉</p></section></article>\n<article id=\"entry-dgp-19625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρασυνία λίμνη (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 578 na letra θ · nº geral 19625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lago Trasimeno, na Etrúria.</p></section></article>\n<article id=\"entry-dgp-19626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 579 na letra θ · nº geral 19626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. at. e inf. aor. pas. θρασυθῆναι) 1 animar; tornar ousado; inspirar coragem 2 vangloriar-se de, ac. ♦ méd. pas. 3 animar-se; tornar-se corajoso, confiante 4 ter confiança excessiva 5 ser muito ousado; ser insolente. 〈θρασύς〉</p></section></article>\n<article id=\"entry-dgp-19627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 580 na letra θ · nº geral 19627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destemido; ousado; corajoso: ἐν τῷ ἔργῳ θρασύς her. ousado em sua empresa 2 confiante: ἐλπὶς θρασεῖα τοῦ μέλλοντος tuc. esperança confiante no futuro 3 que tranqüiliza, que dá segurança; seguro 4 atrevido; arrogante 5 temerário: θρασύ [ἐστι] pínd. é arriscado, inf. 〈θάρσος〉</p></section></article>\n<article id=\"entry-dgp-19628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύσπλαγχνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 581 na letra θ · nº geral 19628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de coração ousado; intrépido. 〈θρασύς, σπλάγχνον〉</p></section></article>\n<article id=\"entry-dgp-19629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασυσπλαγχνῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 582 na letra θ · nº geral 19629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com um coração intrépido; corajosamente.</p></section></article>\n<article id=\"entry-dgp-19630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασυστομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 583 na letra θ · nº geral 19630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falar com ousadia, com insolência. 〈θρα­σύστομος〉</p></section></article>\n<article id=\"entry-dgp-19631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύστομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 584 na letra θ · nº geral 19631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ousado em suas palavras; arrogante; insolente. 〈θρασύς, στόμα〉</p></section></article>\n<article id=\"entry-dgp-19632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύτατα, θρασύτερον</h1><div class=\"entry-meta\"><span>DGP · ordem 585 na letra θ · nº geral 19632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θρασέως.</p></section></article>\n<article id=\"entry-dgp-19633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύτης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 586 na letra θ · nº geral 19633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ousadia; audácia. 〈θρασύς〉</p></section></article>\n<article id=\"entry-dgp-19634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρᾷττα, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 587 na letra θ · nº geral 19634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = Θρᾷσσα.</p></section></article>\n<article id=\"entry-dgp-19635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θράττω</h1><div class=\"entry-meta\"><span>DGP · ordem 588 na letra θ · nº geral 19635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = θράσσω.</p></section></article>\n<article id=\"entry-dgp-19636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραῦμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 589 na letra θ · nº geral 19636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fragmento 2 fratura 3 destruição. 〈θραύω〉</p></section></article>\n<article id=\"entry-dgp-19637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραῦσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 590 na letra θ · nº geral 19637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ruptura; rompimento 2 fratura. 〈θραύω〉</p></section></article>\n<article id=\"entry-dgp-19638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραῦσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 591 na letra θ · nº geral 19638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fragmento; pedaço 2 fratura. 〈θραύω〉</p></section></article>\n<article id=\"entry-dgp-19639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραύω</h1><div class=\"entry-meta\"><span>DGP · ordem 592 na letra θ · nº geral 19639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θραύσω, aor. ἔθραυσα; pas. aor. ἐθραύσθην, perf. τέθραυσμαι) 1 fazer em pedaços; quebrar; despedaçar 2 destruir 3 quebrantar (ânimo).</p></section></article>\n<article id=\"entry-dgp-19640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 593 na letra θ · nº geral 19640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-nascido; rebento; filhote 2 cria; criatura (pessoa, animal doméstico ou selvagem): ὦ θρέμμ᾽ ἀναιδές sóf. ó criatura impudente, δύσκολον τὸ θρ. ἄνθρωπος plat. criatura difícil o homem! 〈τρέφω〉</p></section></article>\n<article id=\"entry-dgp-19641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέξασκον</h1><div class=\"entry-meta\"><span>DGP · ordem 594 na letra θ · nº geral 19641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. iter. de τρέχω.</p></section></article>\n<article id=\"entry-dgp-19642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέξω</h1><div class=\"entry-meta\"><span>DGP · ordem 595 na letra θ · nº geral 19642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de τρέχω.</p></section></article>\n<article id=\"entry-dgp-19643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 596 na letra θ · nº geral 19643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., θρεῦμαι 1 dar grandes gritos 2 bradar (infortúnios), ac. 3 lamentar, ac.</p></section></article>\n<article id=\"entry-dgp-19644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεπτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 597 na letra θ · nº geral 19644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de τρέφω.</p></section></article>\n<article id=\"entry-dgp-19645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεπτήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 598 na letra θ · nº geral 19645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que alimenta; capaz de alimentar 2 que é pagamento da alimentação ♦ τὰ θρεπτήρια 3 pagamento pela alimentação; compensação (dada à ama pelos pais, ou aos pais idosos pelos filhos) 4 alimentação; sustento. 〈τρέφω〉</p></section></article>\n<article id=\"entry-dgp-19646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεπτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 599 na letra θ · nº geral 19646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para criar, alimentar 2 que faz crescer, desenvolver, gen. ♦ τὸ θρεπτικόν 3 princípio de crescimento. 〈θρεπτός〉</p></section></article>\n<article id=\"entry-dgp-19647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 600 na letra θ · nº geral 19647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nutrido. 〈τρέφω〉</p></section></article>\n<article id=\"entry-dgp-19648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέπτρα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 601 na letra θ · nº geral 19648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θρεπτήρια.</p></section></article>\n<article id=\"entry-dgp-19649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεττανελό</h1><div class=\"entry-meta\"><span>DGP · ordem 602 na letra θ · nº geral 19649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">invar. tretaneló; tintiririm, onomatopéia que imita o som da cítara.</p></section></article>\n<article id=\"entry-dgp-19650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 603 na letra θ · nº geral 19650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = θρέομαι.</p></section></article>\n<article id=\"entry-dgp-19651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρεψάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 604 na letra θ · nº geral 19651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. méd. de τρέφω.</p></section></article>\n<article id=\"entry-dgp-19652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέψω</h1><div class=\"entry-meta\"><span>DGP · ordem 605 na letra θ · nº geral 19652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de τρέφω.</p></section></article>\n<article id=\"entry-dgp-19653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρηΐκη, Θρηΐκιος, Θρῆϊξ</h1><div class=\"entry-meta\"><span>DGP · ordem 606 na letra θ · nº geral 19653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Θρᾴκη, Θρᾴκιος, Θρᾷξ.</p></section></article>\n<article id=\"entry-dgp-19654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρῄκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 607 na letra θ · nº geral 19654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de Θρᾴκη.</p></section></article>\n<article id=\"entry-dgp-19655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρῄκηθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 608 na letra θ · nº geral 19655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. da Trácia. 〈Θρῄκη〉</p></section></article>\n<article id=\"entry-dgp-19656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρῄκηνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 609 na letra θ · nº geral 19656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção à Trácia. 〈Θρῄκη〉</p></section></article>\n<article id=\"entry-dgp-19657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρῄκιος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 610 na letra θ · nº geral 19657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de Θρηΐκιος.</p></section></article>\n<article id=\"entry-dgp-19658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 611 na letra θ · nº geral 19658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ép. θρήνεον)1 intr. lamentar-se; chorar; gemer 2 entoar canto de dor 3 emitir com voz lastimosa, ac.: θρ. ᾠδάς sóf. entoar cantos plangentes 4 lamentar-se por; chorar por, ac. ♦ méd. 5 lamentar. 〈θρῆνος〉</p></section></article>\n<article id=\"entry-dgp-19659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνητήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 612 na letra θ · nº geral 19659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θρηνητής.</p></section></article>\n<article id=\"entry-dgp-19660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 613 na letra θ · nº geral 19660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que se lamenta por, gen. 〈θρηνέω〉</p></section></article>\n<article id=\"entry-dgp-19661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 614 na letra θ · nº geral 19661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inclinado a lamentar-se; lamurioso 2 próprio para lamentações ♦ τὸ θρηνητικόν 3 canto lamentoso. 〈θρηνέω〉</p></section></article>\n<article id=\"entry-dgp-19662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῆνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 615 na letra θ · nº geral 19662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pranto; lamento 2 treno; canto fúnebre 3 canto de dor, de lamentação; queixume. 〈θρέομαι〉</p></section></article>\n<article id=\"entry-dgp-19663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῆνυς, υος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 616 na letra θ · nº geral 19663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escabelo 2 banco de remadores.</p></section></article>\n<article id=\"entry-dgp-19664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 617 na letra θ · nº geral 19664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cantar um lamento por, ac. 〈θρηνῳδός〉</p></section></article>\n<article id=\"entry-dgp-19665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 618 na letra θ · nº geral 19665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inclinado à tristeza, à lamúria 2 conveniente às lamentações; lamentável; deplorável (coisas). 〈θρῆνος〉</p></section></article>\n<article id=\"entry-dgp-19666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνῳδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 619 na letra θ · nº geral 19666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">canto de dor, de lamento. 〈θρηνῳδός〉</p></section></article>\n<article id=\"entry-dgp-19667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνῳδός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 620 na letra θ · nº geral 19667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mercenário que pranteava o morto nos funerais; carpidor. 〈θρῆνος, ᾠδή〉</p></section></article>\n<article id=\"entry-dgp-19668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρῇξ</h1><div class=\"entry-meta\"><span>DGP · ordem 621 na letra θ · nº geral 19668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Θρῄξ contr. de Θρῆϊξ.</p></section></article>\n<article id=\"entry-dgp-19669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρησκεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 622 na letra θ · nº geral 19669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 serviço da divindade; culto da divindade; culto de Deus 2 pl. cerimônias religiosas 3 superstição. 〈θρησκεύω〉</p></section></article>\n<article id=\"entry-dgp-19670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρησκεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 623 na letra θ · nº geral 19670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intr. observar normas religiosas 2 celebrar com culto; honrar com cerimônias religiosas (os deuses). 〈θρῆσκος〉</p></section></article>\n<article id=\"entry-dgp-19671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρησκηΐη</h1><div class=\"entry-meta\"><span>DGP · ordem 624 na letra θ · nº geral 19671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = θρησκεία.</p></section></article>\n<article id=\"entry-dgp-19672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῆσκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 625 na letra θ · nº geral 19672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que observa as práticas de um culto religioso; religioso.</p></section></article>\n<article id=\"entry-dgp-19673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρῖα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 626 na letra θ · nº geral 19673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tria, demo da Ática.</p></section></article>\n<article id=\"entry-dgp-19674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριαμβευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 627 na letra θ · nº geral 19674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo ao triunfo. 〈θριαμβεύω〉</p></section></article>\n<article id=\"entry-dgp-19675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριαμβεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 628 na letra θ · nº geral 19675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 triunfar; triunfar sobre alguém, ac., ἀπό ou κατά e gen., ἐπί e dat.: θρ. θρίαμβον plut. celebrar o triunfo, θρ. νίκην plut. celebrar a vitória 2 conduzir em cortejo triunfal (prisioneiro) 3 expor à zombaria (um inimigo vencido) 4 crist. fazer triunfar, ac.: Θεῷ θριαμβεύοντι ἡμᾶς ἐν τῷ Χριστῷ n.t. a Deus que nos faz triunfar em Cristo. 〈θρίαμβος〉</p></section></article>\n<article id=\"entry-dgp-19676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριαμβικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 629 na letra θ · nº geral 19676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que frui as honras do triunfo (pessoa) 2 triunfal; conveniente a um triunfo. 〈θρίαμβος〉</p></section></article>\n<article id=\"entry-dgp-19677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρίαμβος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 630 na letra θ · nº geral 19677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hino cantado nas festas de Dioniso 2 triunfo, epít. de Dioniso Triambos ou Triunfo 3 triunfo, em Roma.</p></section></article>\n<article id=\"entry-dgp-19678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θριάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 631 na letra θ · nº geral 19678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Tria, demo da Ática ♦ τὸ Θριάσιον [πεδίον] 2 planície de Tria, parte da planície de Elêusis. 〈Θρῖα〉</p></section></article>\n<article id=\"entry-dgp-19679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριγγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 632 na letra θ · nº geral 19679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rec. = θριγκός.</p></section></article>\n<article id=\"entry-dgp-19680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριγκίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 633 na letra θ · nº geral 19680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de θριγκός.</p></section></article>\n<article id=\"entry-dgp-19681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριγκός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 634 na letra θ · nº geral 19681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fileira superior; remate (de edifício, de muro) 2 friso 3 muro que circunda; muralha 4 ápice (de infelicidades).</p></section></article>\n<article id=\"entry-dgp-19682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριγκόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 635 na letra θ · nº geral 19682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θριγκώσω, aor. ἐθρίγκωσα) 1 pôr remate em um muro 2 rematar 3 cercar; murar; fechar 4 levar até o mais alto ponto; levar ao auge, ac. 〈θριγκός〉</p></section></article>\n<article id=\"entry-dgp-19683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρίγκωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 636 na letra θ · nº geral 19683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 revestimento da parede; friso; moldura 2 bordas de um altar 3 coroamento: θρ. τῆς τροφῆς plut. coroamento da comida, i.e., o sal. 〈θριγκόω〉</p></section></article>\n<article id=\"entry-dgp-19684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριδάκινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 637 na letra θ · nº geral 19684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de alface 2 semelhante à alface. 〈θρῖδαξ〉</p></section></article>\n<article id=\"entry-dgp-19685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριδάκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 638 na letra θ · nº geral 19685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de θρίδαξ.</p></section></article>\n<article id=\"entry-dgp-19686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῖδαξ</h1><div class=\"entry-meta\"><span>DGP · ordem 639 na letra θ · nº geral 19686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e θρίδαξ, ακος (ἡ) alface.</p></section></article>\n<article id=\"entry-dgp-19687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 640 na letra θ · nº geral 19687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. ἔθρισα) poét., sinc. de θερίζω.</p></section></article>\n<article id=\"entry-dgp-19688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῖναξ</h1><div class=\"entry-meta\"><span>DGP · ordem 641 na letra θ · nº geral 19688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e θρίναξ, ακος (ὁ) tridente. 〈τρίς〉</p></section></article>\n<article id=\"entry-dgp-19689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρίξ, τριχός,</h1><div class=\"entry-meta\"><span>DGP · ordem 642 na letra θ · nº geral 19689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. θριξί (ἡ) 1 pêlo 2 pl. cabelos; no sing. com sent. col., cabeleira: τριχὸς πλόκαμος ésql. trança de cabelos 3 barba 4 crina ou rabo do cavalo 5 tufo de pêlo de carneiro; tosão; lã 6 cerdas de porco 7 plumas.</p></section></article>\n<article id=\"entry-dgp-19690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριπήδεστος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 643 na letra θ · nº geral 19690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον (superl. θριπηδέστατος) 1 corroído por vermes; carunchoso 2 feito com madeira corroída ou com entalhes que lembram a madeira corroída (selo). 〈θρίψ, ἐδεστός〉</p></section></article>\n";
